{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C49"],
      "claim": "Acamprosate absolute oral bioavailability was 11 ± 1% in healthy male volunteers after a 666 mg oral tablet dose compared with IV (C49), below the 20% threshold."
    },
    {
      "card_ids": ["C40"],
      "claim": "Tegaserod mean absolute oral bioavailability was approximately 10% in healthy volunteers across 2–12 mg oral doses (C40), below the 20% threshold."
    },
    {
      "card_ids": ["C20"],
      "claim": "Oseltamivir carboxylate absolute oral bioavailability was 79.0% ± 11.6% in healthy volunteers after oral oseltamivir 150 mg versus IV Ro 64-0802 (C20), above the 20% threshold, but this high-bioavailability evidence has lower assay-transfer and conflicting <5% records."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C20"],
  "decision_summary": "The highest-transfer, direct absolute-bioavailability evidence (acamprosate, tegaserod) is below 20%, and additional lower-transfer molecules (ferulic acid, indoramin, THU, aluminum) also support low; high-bioavailability evidence from oseltamivir is less transferable and conflicted, so low is better supported.",
  "evidence_gaps": [
    "Molecule 4 has conflicting oseltamivir carboxylate bioavailability records (<5% in C51/C14 vs ~80% in C20/C10); the absolute comparator records were prioritized.",
    "Molecule 10 contains a provenance conflict between finasartan (C36) and finasteride records; C36 was discounted.",
    "Molecule 5 naltrexone tablet bioavailability range 5–40% straddles the 20% threshold and is uninformative."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C49", "C40"],
  "revision_action": "initial",
  "supportive_card_ids": ["C49", "C40"]
}

